$page_title='โปรโมชั่นและคูปอง'; require_once __DIR__.'/../includes/auth_check.php'; requireAdmin(); require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/image_upload.php';
$db=(new Database())->getConnection();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf(false);$action=$_POST['action']??'';try{
 if($action==='coupon'){ $code=strtoupper(trim($_POST['code']??''));$title=trim($_POST['title']??'');$type=$_POST['discount_type']??'percent';$value=(float)($_POST['discount_value']??0);$min=(float)($_POST['min_order_amount']??0);$max=(float)($_POST['max_discount']??0)?:null;$limit=(int)($_POST['usage_limit']??0)?:null;$category=(int)($_POST['category_id']??0)?:null;$product=(int)($_POST['product_id']??0)?:null;$start=$_POST['starts_at']??date('Y-m-d H:i:s');$end=$_POST['ends_at']??date('Y-m-d H:i:s',strtotime('+30 days'));if(!preg_match('/^[A-Z0-9_-]{3,40}$/',$code)||$title===''||$value<0)throw new RuntimeException('กรุณากรอกข้อมูลคูปองให้ถูกต้อง');$s=$db->prepare('INSERT INTO coupons(code,title,description,discount_type,discount_value,max_discount,min_order_amount,usage_limit,per_user_limit,category_id,product_id,starts_at,ends_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$code,$title,trim($_POST['description']??''),$type,$value,$max,$min,$limit,max(1,(int)($_POST['per_user_limit']??1)),$category,$product,$start,$end]);$message='สร้างคูปองเรียบร้อยแล้ว';
 } elseif($action==='banner'){ $title=trim($_POST['title']??'');$placement=$_POST['placement']??'floating';$desktop='';if(isset($_FILES['image_desktop'])&&$_FILES['image_desktop']['error']!==UPLOAD_ERR_NO_FILE)$desktop=saveBannerImageUpload($_FILES['image_desktop']);if($title===''||$desktop==='')throw new RuntimeException('กรุณากรอกชื่อและอัปโหลดรูป Desktop');$mobile=null;if(isset($_FILES['image_mobile'])&&$_FILES['image_mobile']['error']!==UPLOAD_ERR_NO_FILE)$mobile=saveBannerImageUpload($_FILES['image_mobile']);$s=$db->prepare('INSERT INTO promotional_banners(title,subtitle,image_desktop,image_mobile,button_label,target_url,placement,coupon_id,starts_at,ends_at,sort_order,is_active) VALUES(?,?,?,?,?,?,?,?,?,?,?,1)');$coupon=(int)($_POST['coupon_id']??0)?:null;$s->execute([$title,trim($_POST['subtitle']??''),$desktop,$mobile,trim($_POST['button_label']??''),trim($_POST['target_url']??''),$placement,$coupon,$_POST['starts_at']??date('Y-m-d H:i:s'),$_POST['ends_at']??date('Y-m-d H:i:s',strtotime('+30 days')),(int)($_POST['sort_order']??0)]);$message='เพิ่มแบนเนอร์เรียบร้อยแล้ว';
 } elseif($action==='toggle_banner'){ $s=$db->prepare('UPDATE promotional_banners SET is_active=1-is_active WHERE id=?');$s->execute([(int)$_POST['id']]);$message='อัปเดตสถานะแบนเนอร์แล้ว'; }
}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'ไม่สามารถบันทึกข้อมูลได้';}}
$coupons=$db?$db->query('SELECT * FROM coupons ORDER BY id DESC')->fetchAll():[];$categories=$db?$db->query('SELECT id,name FROM categories ORDER BY name')->fetchAll():[];$products=$db?$db->query("SELECT id,name FROM products WHERE approval_status='approved' ORDER BY name")->fetchAll():[];$banners=$db?$db->query('SELECT b.*,c.code coupon_code FROM promotional_banners b LEFT JOIN coupons c ON c.id=b.coupon_id ORDER BY b.id DESC')->fetchAll():[];require_once __DIR__.'/../includes/admin_header.php';
